INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.choque.evento', 'La parte del {fecha} no alcanzó', 'Evento del contexto de choque.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.cuenta.titulo', 'Tu cuenta quedó abierta', 'Aviso al abrir la cuenta.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.cuenta.cuerpo', '{producto} {numero}. Sin costo y sin saldo mínimo: de aquí se aparta y de aquí se paga.', 'Aviso al abrir la cuenta.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.deposito.titulo', 'Tu depósito a plazo quedó activo', 'Aviso al activar el depósito.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.deposito.cuerpo', 'Crece a tasa fija y te avisamos cuando venza. Lo ves en tus productos.', 'Aviso al activar el depósito.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.cita.titulo', 'Tu asistencia quedó agendada', 'Aviso al agendar.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.cita.cuerpo', '{cuando} con {asesora} en {donde}. Ya sabe que es sobre tu {tema}.', 'Aviso al agendar.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.acuerdo.titulo', 'Guardamos lo que acordamos', 'Aviso al cerrar un acuerdo en el chat.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('aviso.acuerdo.cuerpo', '{detalle} Lo ves en tu inicio.', 'Aviso al cerrar un acuerdo en el chat.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.sumando.fecha', 'Cambiaste tu fecha de cobro', 'Lo que suma al récord.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.sumando.apartas', 'Apartas tu cuota en partes', 'Lo que suma al récord.');
