INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.explicacion', 'Cada cuota a tiempo suma un mes a tu récord. Lo que no fue a tiempo sale solo, en su fecha.', 'Explicación del camino a 24 de 24.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.explicacion.salida', 'Lo que no fue a tiempo sale de tu récord en su fecha ({fechas}). Mientras, cada cuota a tiempo suma.', 'Explicación cuando hay salidas.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.suma.detalle.apartas', 'Tu cuota queda completa antes de la fecha. El dinero se congela en tu cuenta y se paga entero ese día.', 'Detalle de lo que suma.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.suma.detalle.linea', 'Usas el {pct} % de tu línea. Por debajo del 50 %: tienes espacio y lo cuidas.', 'Detalle de lo que suma.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.suma.detalle.generico', 'Cada mes a tiempo se suma a tu historial con nosotros.', 'Detalle de lo que suma.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('record.proximo', 'Tu próximo +1: {fecha}', 'Etiqueta del próximo +1.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('resumen.personal', 'va al día: tu cuota es de {monto}', 'Resumen de crédito personal al día.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('resumen.card', 'va al día: tu pago de contado es de {monto}', 'Resumen de tarjeta al día.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('resumen.cuenta', 'tiene {monto} disponibles', 'Resumen de una cuenta.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('resumen.parte_pendiente', 'tiene una parte de {monto} por acomodar, y tiene arreglo', 'Resumen cuando una parte quedó corta.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('resumen.otro', 'está en orden', 'Resumen sin producto específico.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('cita.cuando', '{dia} · {hora}', 'Cuándo es la asistencia.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('cita.donde', 'Agencia {agencia}', 'Dónde es la asistencia.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('cita.sobre', 'tu {tema}', 'Sobre qué es la asistencia.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('cita.nota', '{asesora} ya sabe que es sobre tu {tema}, así llegas y van al grano.', 'Confirmación de la asistencia.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('apertura.debe_aceptar', 'Para abrir tu cuenta necesitamos que aceptes las condiciones.', 'Mensaje si no se aceptan las condiciones.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('demo.deposito_apertura', 'cust-mauricio-sosa=640.00,cust-samuel-quijada=420.00,cust-gabriela-romero=560.00,cust-fatima-argueta=380.00,cust-rene-aguilar=120.00', 'Demo: su primer ingreso ya acreditado al abrir la cuenta, para que quien no tenía cuenta tenga saldo que apartar. Ilustrativo: vacío en producción.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.max_turnos', '30', 'Turnos del cliente antes de escalar a una persona (MAX_MESSAGES_BEFORE_ESCALATION).');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.historial_max', '12', 'Mensajes recientes que se envían como contexto al modelo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.tiers_asesora', 'platino,black', 'Tarjetas que escalan a su asesora nombrada. El resto va al Centro de Atención.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.rechazos.diligente', '2', 'Rechazos seguidos antes de escalar.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.rechazos.olvidadizo', '2', 'Rechazos seguidos antes de escalar.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.rechazos.resistente', '1', 'Un solo intento: insistirle no es cuidado, es ruido.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.rechazos.despreocupado', '2', 'Rechazos seguidos antes de escalar.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.orden.diligente', 'qr-fecha,qr-apartar,qr-automatico,qr-asesora,qr-lo-pienso', 'Orden de ofertas (tono), nunca cambia monto ni plazo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.orden.olvidadizo', 'qr-automatico,qr-apartar,qr-fecha,qr-asesora,qr-lo-pienso', 'Orden de ofertas (tono), nunca cambia monto ni plazo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.orden.resistente', 'qr-apartar,qr-fecha,qr-asesora', 'Orden de ofertas (tono), nunca cambia monto ni plazo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.orden.despreocupado', 'qr-fecha,qr-apartar,qr-automatico,qr-asesora,qr-lo-pienso', 'Orden de ofertas (tono), nunca cambia monto ni plazo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.tono.diligente', 'Buen historial y primera vez cerca de un tropiezo: tono ligero y confiado.', 'Guía de tono para el modelo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.tono.olvidadizo', 'El problema es la memoria, no la voluntad: sugiere dejarlo en automático.', 'Guía de tono para el modelo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.tono.resistente', 'Breve y directo, un solo intento, sin insistir.', 'Guía de tono para el modelo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.tono.despreocupado', 'Nombra lo que le suma en su récord al resolverlo, sin volverlo castigo.', 'Guía de tono para el modelo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.tranquilidad', 'Le pasa a cualquiera, y tiene arreglo.', 'Frase de tranquilidad por defecto.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.apertura.general', 'Hola, {nombre}. Estoy aquí para ayudarte con tus pagos y tu crédito. La mayoría lo resuelve moviendo la fecha de cobro o apartando la cuota en partes. ¿Qué te gustaría hacer?', 'Primer mensaje sin evento de choque.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.apertura.shock.diligente', '{nombre}, vi que {evento}. {tranquilidad} La mayoría de clientes como tú lo resuelve moviendo la fecha de cobro o apartando la cuota en partes. ¿Cuál te acomoda?', 'Apertura tras un choque.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.apertura.shock.olvidadizo', '{nombre}, vi que {evento}. {tranquilidad} Si quieres, lo dejamos en automático para que no vuelva a pasar. ¿Lo vemos?', 'Apertura tras un choque.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.apertura.shock.resistente', '{nombre}, vi que {evento}. Tengo dos formas de resolverlo ahora mismo: apartar la cuota en partes o mover la fecha de cobro.', 'Apertura tras un choque.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.apertura.shock.despreocupado', '{nombre}, vi que {evento}. Resolverlo ahora te sigue sumando en tu récord, y tiene arreglo fácil. ¿Movemos la fecha o apartamos en partes?', 'Apertura tras un choque.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.ofertas', 'La mayoría de clientes como tú lo resuelve con alguna de estas opciones, {nombre}. ¿Cuál te acomoda?', 'Ofertas concretas.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.pregunta.interes', '{costo} ¿La cambio al día {dia}, {nombre}?', 'Chat: el día elegido corre la cuota. Se pregunta antes de mover la fecha.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.costo.interes', 'Esa primera cuota lleva {monto} de interés, una sola vez.', 'Chat: interés aceptado.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.costo.sin_interes', 'Tu cuota y tu plazo no cambian.', 'Chat: sin interés.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.acuerdo.fecha', 'Listo, {nombre}. Tu cobro ahora es el día {dia}, desde el {fecha}. {costo} Ya quedó guardado en tu inicio.', 'Acuerdo: cambiar fecha (ejecutado en el mismo turno).');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.acuerdo.apartar', 'Perfecto, {nombre}. Apartamos {monto} en {partes} y se paga completo el {fecha}. Apartar no es pagar antes: el dinero sigue siendo tuyo. Tu ruta ya quedó activa.', 'Acuerdo: apartar (ejecutado en el mismo turno).');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.acuerdo.automatico', 'Hecho, {nombre}. Lo dejamos en automático desde tu cuenta {cuenta}: de ahí se aparta y de ahí se paga el {fecha}. Puedes quitarlo cuando quieras.', 'Acuerdo: automático.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.pregunta.frecuencia', 'Para acomodarlo a tus pagos, {nombre}: ¿qué día te pagan?', 'El chat pregunta la frecuencia de pago antes de mover la fecha o apartar.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.pregunta.dia', 'Estos días caen después de que te pagan, {nombre}. Si alguno corre tu cuota, te digo el interés antes de cambiarla. ¿Cuál te queda mejor?', 'El chat ofrece los días válidos.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.pregunta.partes', '¿En cuántas partes la apartamos, {nombre}? {nota}', 'El chat ofrece las partes permitidas.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.sin_cuenta', 'Para apartar necesitamos una cuenta tuya con nosotros, {nombre}: de ahí se congela y de ahí se paga. La abres en dos minutos desde «Apartar mi cuota» en tu inicio, sin costo.', 'Apartar sin cuenta propia.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.sin_credito', 'No veo un crédito con cuota en tus productos, {nombre}. Si quieres, lo revisamos con {asesora}.', 'Sin crédito apartable.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.ya_tiene_ruta', 'Tu ruta ya está activa, {nombre}: apartamos {monto} en {partes} y se paga el {fecha}. ¿Quieres cambiar algo?', 'Ya existe un apartado activo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.fecha_invalida', 'Ese día no cae después de tu pago, {nombre}. Te dejo los que sí:', 'El día pedido no está en el set permitido.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.pregunta.libre', 'Con gusto, {nombre}. {respuesta}', 'Prefijo para respuestas libres del modelo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.siguiente_paso', 'Claro, {nombre}, piénsalo con calma. Tus opciones quedan a mano en tu inicio: cuando quieras, tocas «Apartar mi cuota» o «Cambiar fecha de cobro» y lo resuelves en tres toques.', 'Cierre con siguiente paso concreto.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.rechazo.suave', 'Sin problema, {nombre}. ¿Te sirve alguna de estas otras opciones?', 'Tras un rechazo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.rechazo.ultimo', 'Entiendo, {nombre}. Antes de pasarte con una persona, ¿alguna de estas te sirve?', 'Último intento antes de escalar.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.escalar.asesora', 'Entiendo, {nombre}. Esto lo vemos mejor con {asesora}, sin costo. ¿Agendamos una asistencia?', 'Escalamiento a la asesora nombrada.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.escalar.centro', 'Entiendo, {nombre}. Lo vemos mejor con el Centro de Atención al Cliente, con calma y sin costo. ¿Quieres que te contacten?', 'Escalamiento al Centro de Atención.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.escalar.turnos', 'Llevamos un buen rato, {nombre}, y quiero que esto quede resuelto.', 'Prefijo al escalar por límite de turnos.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.cita.agendada', 'Listo, {nombre}: {cuando} con {asesora} en {donde}. Ya sabe que es sobre tu {tema}.', 'Confirmación de asistencia desde el chat.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.centro.confirmado', 'Listo, {nombre}. El Centro de Atención al Cliente te contacta en horario hábil para revisar tu caso con calma.', 'Confirmación de contacto del Centro de Atención.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.negativa', 'Está bien, {nombre}, no insisto. Si más adelante quieres verlo, aquí estoy.', 'Cierre ante una negativa explícita.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.redireccion', 'Puedo ayudarte con tu crédito y tus pagos, {nombre}. ¿Seguimos con eso? La mayoría lo resuelve moviendo la fecha de cobro o apartando la cuota en partes.', 'Redirección ante temas ajenos.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.jailbreak', 'Mi tarea es ayudarte con tus pagos y tu crédito, {nombre}, y ahí me quedo. ¿Seguimos con lo tuyo?', 'Respuesta ante intentos de cambiar las reglas.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('chat.cerrado', 'Tu conversación quedó resuelta, {nombre}. Si necesitas algo más, cuéntame y lo vemos.', 'Mensaje en una conversación ya cerrada.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('form.razon_heuristica', 'Te sugerimos esta opción como punto de partida. Tú decides.', 'Motivo cuando la sugerencia no viene de un modelo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('form.sin_opciones', 'No hay opciones para recomendar.', 'Respuesta si el formulario no trae opciones.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('push.tipo', 'corte-cercano', 'Tipo del aviso preventivo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('push.titulo', 'Tu corte se acerca y hay opciones', 'Título del push preventivo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('push.cuerpo', '{nombre}, faltan {dias} días para tu corte. La mayoría lo resuelve moviendo la fecha o repartiendo la cuota. Toca para verlo.', 'Cuerpo del push preventivo.');
INSERT INTO PARAMETRO_APP (clave, valor, descripcion) VALUES ('push.cuerpo_un_dia', '{nombre}, falta 1 día para tu corte. La mayoría lo resuelve moviendo la fecha o repartiendo la cuota. Toca para verlo.', 'Cuerpo del push a un día del corte.');
